/*
 * Share links. The app routes with #hashes, which link previews ignore, so shared links point
 * at small static pages (/test/<id>/, /leaderboards/) that carry their own social card and
 * send visitors straight on to the app. They're generated by `npm run build:social`.
 */
export const SITE = 'https://reaction.retrac.space';

export const testShareUrl = (id) => `${SITE}/test/${id}/`;
export const leaderboardsShareUrl = () => `${SITE}/leaderboards/`;

/**
 * Shares a link with the system share sheet where there is one, otherwise copies it.
 * Resolves to 'shared', 'copied', or 'failed'. Cancelling the share sheet counts as 'shared'.
 */
export async function shareLink({ url, title, text }) {
  if (navigator.share) {
    try {
      await navigator.share({ url, title, text });
      return 'shared';
    } catch (error) {
      if (error && error.name === 'AbortError') return 'shared';
    }
  }
  try {
    await navigator.clipboard.writeText(text ? `${text} ${url}` : url);
    return 'copied';
  } catch {
    return 'failed';
  }
}
